#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "pack_builder.h"
#include "pack_template.h"
#include "word_pack.h"

#define MAX_SCREEN_CELLS 24
#define MIN_TOLERANCE 2
#define TOLERANCE_DIVISOR 8
#define NO_LIST (-1)
#define MAIN_BANK_FILE "words.tsv"
#define KIDS_BANK_FILE "kids.tsv"
#define SEQUENCE_FILE "sequence.txt"
#define GENERATED_LIST_HEADER "# generated by todmod_config from "

typedef struct {
    char *display;
    char *reading;
    int difficulty;
    int uses;
    int last_list;
} word_entry;

typedef struct {
    word_entry *entries;
    int count;
    unsigned random_state;
} word_pool;

static char *read_text_file(const char *path) {
    FILE *file = fopen(path, "rb");
    if (!file) return NULL;
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);
    char *text = malloc(size + 1);
    size_t read = fread(text, 1, size, file);
    fclose(file);
    text[read] = '\0';
    return text;
}

static char *trim(char *text) {
    while (*text == ' ' || *text == '\t' || *text == '\r') text++;
    char *end = text + strlen(text);
    while (end > text && (end[-1] == ' ' || end[-1] == '\t' || end[-1] == '\r')) *--end = '\0';
    return text;
}

static int compare_entries(const void *a, const void *b) {
    const word_entry *x = a, *y = b;
    if (x->difficulty != y->difficulty) return x->difficulty - y->difficulty;
    int display = strcmp(x->display, y->display);
    return display ? display : strcmp(x->reading ? x->reading : "", y->reading ? y->reading : "");
}

static void add_entry(word_pool *pool, int *capacity, char *display, char *reading, pack_build_report *report) {
    int glyphs = 0;
    int difficulty = word_pack_entry_difficulty(display, reading, &glyphs);
    if (!difficulty) {
        report->untypable++;
        return;
    }
    if (glyphs > MAX_SCREEN_CELLS) {
        report->too_long++;
        return;
    }
    if (pool->count == *capacity) {
        *capacity = *capacity ? *capacity * 2 : 1024;
        pool->entries = realloc(pool->entries, *capacity * sizeof *pool->entries);
    }
    word_entry *entry = &pool->entries[pool->count++];
    entry->display = _strdup(display);
    entry->reading = reading && *reading ? _strdup(reading) : NULL;
    entry->difficulty = difficulty;
    entry->uses = 0;
    entry->last_list = NO_LIST;
}

static void read_word_list(char *text, word_pool *pool, pack_build_report *report) {
    int capacity = 0;
    char *line = text;
    if ((unsigned char)line[0] == 0xEF && (unsigned char)line[1] == 0xBB && (unsigned char)line[2] == 0xBF) line += 3;
    while (line) {
        char *newline = strchr(line, '\n');
        if (newline) *newline = '\0';
        char *content = trim(line);
        if (*content && *content != '#') {
            report->words_read++;
            char *tab = strchr(content, '\t');
            char *reading = NULL;
            if (tab) {
                *tab = '\0';
                reading = trim(tab + 1);
                content = trim(content);
            }
            if (*content) add_entry(pool, &capacity, content, reading, report);
        }
        line = newline ? newline + 1 : NULL;
    }
}

static int write_sequence(const char *pack_folder, const word_pool *pool, const char *source_name) {
    char path[MAX_PATH];
    snprintf(path, sizeof path, "%s\\%s", pack_folder, SEQUENCE_FILE);
    FILE *file = fopen(path, "wb");
    if (!file) return 0;
    fprintf(file, "# usable lines of %s in their original order (for [dictionary] in_order=1)\n", source_name);
    for (int i = 0; i < pool->count; i++) {
        const word_entry *entry = &pool->entries[i];
        if (entry->reading) {
            fprintf(file, "%s\t%s\n", entry->display, entry->reading);
        } else {
            fprintf(file, "%s\n", entry->display);
        }
    }
    return fclose(file) == 0;
}

static void remove_duplicates(word_pool *pool, pack_build_report *report) {
    qsort(pool->entries, pool->count, sizeof *pool->entries, compare_entries);
    int kept = 0;
    for (int i = 0; i < pool->count; i++) {
        if (kept && compare_entries(&pool->entries[kept - 1], &pool->entries[i]) == 0) {
            free(pool->entries[i].display);
            free(pool->entries[i].reading);
            report->duplicates++;
            continue;
        }
        pool->entries[kept++] = pool->entries[i];
    }
    pool->count = kept;
}

static unsigned next_random(word_pool *pool) {
    unsigned x = pool->random_state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return pool->random_state = x;
}

static int first_at_or_above(const word_pool *pool, int difficulty) {
    int low = 0, high = pool->count;
    while (low < high) {
        int middle = (low + high) / 2;
        if (pool->entries[middle].difficulty < difficulty) low = middle + 1;
        else high = middle;
    }
    return low;
}

static int pick_within(word_pool *pool, int difficulty, int tolerance, int list, int allow_repeat_in_list) {
    int start = first_at_or_above(pool, difficulty - tolerance);
    int best = -1, best_uses = 0, ties = 0;
    for (int i = start; i < pool->count && pool->entries[i].difficulty <= difficulty + tolerance; i++) {
        const word_entry *entry = &pool->entries[i];
        if (!allow_repeat_in_list && entry->last_list == list) continue;
        if (best < 0 || entry->uses < best_uses) {
            best = i, best_uses = entry->uses, ties = 1;
        } else if (entry->uses == best_uses && next_random(pool) % ++ties == 0) {
            best = i;
        }
    }
    return best;
}

static word_entry *pick_entry(word_pool *pool, int difficulty, int list) {
    int tolerance = difficulty / TOLERANCE_DIVISOR > MIN_TOLERANCE ? difficulty / TOLERANCE_DIVISOR : MIN_TOLERANCE;
    int widest = pool->entries[pool->count - 1].difficulty + difficulty;
    for (int allow_repeat = 0; allow_repeat <= 1; allow_repeat++) {
        for (int t = tolerance; ; t *= 2) {
            int index = pick_within(pool, difficulty, t, list, allow_repeat);
            if (index >= 0) return &pool->entries[index];
            if (t > widest) break;
        }
    }
    return &pool->entries[0];
}

static void write_entry(FILE *file, const char *list_name, const word_entry *entry) {
    fprintf(file, "%s\tauto\t%s", list_name, entry->display);
    if (entry->reading) fprintf(file, "\t%s", entry->reading);
    fputc('\n', file);
}

static void write_list(FILE *file, word_pool *pool, int list_index) {
    const template_list *list = &template_lists[list_index];
    for (int slot = 0; slot < list->slot_count; slot++) {
        word_entry *entry = pick_entry(pool, template_difficulties[list->first_slot + slot], list_index);
        entry->uses++;
        entry->last_list = list_index;
        write_entry(file, list->name, entry);
    }
}

static void remove_generated_list_files(const char *folder) {
    char pattern[MAX_PATH];
    snprintf(pattern, sizeof pattern, "%s\\*.txt", folder);
    WIN32_FIND_DATAA found;
    HANDLE search = FindFirstFileA(pattern, &found);
    if (search == INVALID_HANDLE_VALUE) return;
    do {
        char path[MAX_PATH], first_line[64] = "";
        snprintf(path, sizeof path, "%s\\%s", folder, found.cFileName);
        FILE *file = fopen(path, "rb");
        if (!file) continue;
        fgets(first_line, sizeof first_line, file);
        fclose(file);
        if (strncmp(first_line, GENERATED_LIST_HEADER, strlen(GENERATED_LIST_HEADER)) == 0) DeleteFileA(path);
    } while (FindNextFileA(search, &found));
    FindClose(search);
    RemoveDirectoryA(folder);
}

static FILE *open_bank_file(const char *pack_folder, const char *file_name, const char *source_name) {
    char path[MAX_PATH];
    snprintf(path, sizeof path, "%s\\%s", pack_folder, file_name);
    FILE *file = fopen(path, "wb");
    if (file) fprintf(file, "# generated by todmod_config from %s: list<TAB>difficulty<TAB>display<TAB>reading\n", source_name);
    return file;
}

static void free_pool(word_pool *pool) {
    for (int i = 0; i < pool->count; i++) {
        free(pool->entries[i].display);
        free(pool->entries[i].reading);
    }
    free(pool->entries);
}

int build_pack_from_word_list(const char *word_list_path, const char *pack_folder, unsigned seed,
                              pack_build_report *report, char *error, size_t error_size) {
    memset(report, 0, sizeof *report);
    char *text = read_text_file(word_list_path);
    if (!text) {
        snprintf(error, error_size, "Cannot read %s.", word_list_path);
        return 0;
    }
    word_pool pool = {NULL, 0, seed ? seed : 0x2545F491u};
    read_word_list(text, &pool, report);
    free(text);
    const char *source_name = strrchr(word_list_path, '\\') ? strrchr(word_list_path, '\\') + 1 : word_list_path;
    if (pool.count) {
        CreateDirectoryA(pack_folder, NULL);
        if (!write_sequence(pack_folder, &pool, source_name)) {
            snprintf(error, error_size, "Cannot write %s into %s.", SEQUENCE_FILE, pack_folder);
            free_pool(&pool);
            return 0;
        }
    }
    remove_duplicates(&pool, report);
    report->words_usable = pool.count;
    if (!pool.count) {
        snprintf(error, error_size, "No usable words: every line was empty, untypable or too long for the screen (%d cells).",
                 MAX_SCREEN_CELLS);
        free_pool(&pool);
        return 0;
    }
    FILE *banks[2] = {open_bank_file(pack_folder, MAIN_BANK_FILE, source_name),
                      open_bank_file(pack_folder, KIDS_BANK_FILE, source_name)};
    if (!banks[0] || !banks[1]) {
        if (banks[0]) fclose(banks[0]);
        if (banks[1]) fclose(banks[1]);
        snprintf(error, error_size, "Cannot write word lists into %s.", pack_folder);
        free_pool(&pool);
        return 0;
    }
    for (int i = 0; i < template_list_count; i++) {
        if (template_lists[i].keep_original) {
            report->lists_kept++;
            continue;
        }
        write_list(banks[template_lists[i].kids], &pool, i);
        report->lists_written++;
        report->slots_filled += template_lists[i].slot_count;
    }
    int written = (fclose(banks[0]) == 0) & (fclose(banks[1]) == 0);
    free_pool(&pool);
    if (!written) {
        snprintf(error, error_size, "Cannot write word lists into %s.", pack_folder);
        return 0;
    }
    char kids_folder[MAX_PATH];
    snprintf(kids_folder, sizeof kids_folder, "%s\\kids", pack_folder);
    remove_generated_list_files(kids_folder);
    remove_generated_list_files(pack_folder);
    return 1;
}
